export const LANGUAGE_STORAGE_KEY='path-recognize-language';
let language='zh';
try { const saved=globalThis.localStorage?.getItem(LANGUAGE_STORAGE_KEY); if(saved==='en')language='en'; } catch {}
export function getLanguage(){return language;}
export function t(key,params={}){
 const text=language==='en'?(messages[key]??key):key;
 return text.replace(/\{(\w+)\}/g,(_,name)=>String(params[name]??'{'+name+'}'));
}
export function applyTranslations(root=document){
 root.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));
 for(const attr of ['aria-label','title','content'])root.querySelectorAll('[data-i18n-'+attr+']').forEach(el=>el.setAttribute(attr,t(el.getAttribute('data-i18n-'+attr))));
 document.documentElement.lang=language==='zh'?'zh-CN':'en';
 root.querySelectorAll('[data-language]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.language===language)));
}
export function setLanguage(next){
 if(next!=='zh'&&next!=='en')throw new RangeError('Supported languages: zh, en');
 language=next;try{globalThis.localStorage?.setItem(LANGUAGE_STORAGE_KEY,next);}catch{}
 if(typeof document!=='undefined'){applyTranslations();window.dispatchEvent(new CustomEvent('path-recognize:language',{detail:{language:next}}));}
 return next;
}
export function initI18n(){
 applyTranslations();
 document.querySelectorAll('[data-language]').forEach(button=>button.addEventListener('click',()=>setLanguage(button.dataset.language)));
}
